void henge_gl_set_backend(void *(*resolve)(const char *)) { g_resolver = resolve; }
void *hr_gl_lookup(const char *name) {
    size_t lo = 0, hi = sizeof entries / sizeof entries[0];
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        int cmp = strcmp(name, entries[mid].name);
        if (!cmp) {
            void *fn = g_resolver ? g_resolver(name) : dlsym(RTLD_DEFAULT, name);
            if (!fn) return NULL;
            atomic_store(entries[mid].target, fn);
            return entries[mid].bridge;
        }
        if (cmp < 0) hi = mid; else lo = mid + 1;
    }
    return NULL;
}
